WITH products_by_supplier AS (SELECT supplier_id, ROUND((100 * SUM(CASE WHEN brand = 'Initech' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_initech, MAX(stock_qty) max_stock_qty FROM products WHERE launch_date BETWEEN '2023-03-01' AND '2024-10-31' GROUP BY supplier_id) SELECT s.id, s.city, s.rating, pbs.pct_initech, pbs.max_stock_qty FROM suppliers s INNER JOIN products_by_supplier pbs ON s.id = pbs.supplier_id ORDER BY pct_initech DESC, pbs.max_stock_qty DESC, id LIMIT 20;
